  "about_items": [
    {
      "n": "#13·23",
      "text": "A structured grey blazer with a single-button closure and wide lapels that offer a refined, timeless silhouette. It sits cleanly over the top half of your figure, adding polish while maintaining comfort for a formal occasion."
    },
    {
      "n": "#195·36",
      "text": "A flowing light grey midi skirt with a smooth drape and a small slit at the back for movement. Its relaxed cut contrasts gently with the fitted blazer, creating balance while allowing grace and ease through the day."
    },
    {
      "n": "#209·31",
      "text": "A narrow tan leather belt with a polished silver buckle that defines your waist without adding bulk. It brings warmth to the cool-toned palette and anchors the outfit at its most important line."
    },
    {
      "n": "#42·03",
      "text": "Classic blue suede loafers with a soft, textured finish and a subtle metallic charm detail on the strap. Their rounded toe and low profile make them ideal for long hours of standing or walking, while their muted tone blends effortlessly with the rest of your look."
    },
    {
      "n": "#326·03",
      "text": "A sleek black leather handbag with clean lines and a minimalist design. Its smooth texture and structured shape carry just enough presence to complete the outfit without drawing attention away from you."
    }
  ]
}
